mapper.select:
SELECT t.* FROM erp_finance_voucher_template t WHERE t.deleted = 0
AND t.ledger_id IN #{ledgerId}
AND t.ledger_id = #{reqVO.ledgerId}
AND t.biz_type = #{reqVO.bizType}
AND t.name LIKE CONCAT('%', #{reqVO.name}, '%')
AND t.status = #{reqVO.status}
AND t.auto_generate = #{reqVO.autoGenerate}

    AND (
        (t.ledger_id != #{ledgerId} OR NOT EXISTS (SELECT 1 FROM erp_finance_voucher_template_item i
        WHERE i.template_id = t.id AND i.deleted = 0 AND i.subject_code NOT IN
        #{subjectCode}))
    )

ORDER BY t.id DESC
